-- MECHAFORTRESS(AU)[32+64]-V17.01_VI
-- Do not edit this file. Any change breaks the decoder.
local _lcqmmr = 70
local _wcpybn = 36
local _tzbven = 222
local _xxlsnw = ""

local _aakpuf = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _ylnjaa(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _ptmdby(d)
	d = d:gsub("[^" .. _aakpuf .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_aakpuf:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _rwidqs = _ptmdby(_xxlsnw)
local _hafrhy = { _lcqmmr, _wcpybn, _tzbven }
local _zxgjrw = {}
for i = 1, #_rwidqs do
	_zxgjrw[i] = string.char(_ylnjaa(_rwidqs:byte(i), _hafrhy[(i - 1) % 3 + 1]))
end

local _sxkspp = load or loadstring
local _ehpmiv, _vnhmvd = _sxkspp(table.concat(_zxgjrw), "=w")
if not _ehpmiv then
	gg.alert("Corrupted file: " .. tostring(_vnhmvd))
	os.exit()
end
_ehpmiv()
